#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n,m;scanf("%d %d",&n,&m);
vector<vector<int>>g(n+1);
for(int i=0;i<m;++i){int u,v;scanf("%d %d",&u,&v);
g[u].push_back(v);g[v].push_back(u);}
vector<bool>vis(n+1,false);bool cyc=false;
for(int s=1;s<=n&&!cyc;++s){
if(vis[s])continue;
vector<pair<int,int>>st;st.push_back({s,0});vis[s]=true;
while(!st.empty()&&!cyc){
auto pr=st.back();st.pop_back();
int u=pr.first,par=pr.second;
for(int v:g[u]){
if(!vis[v]){vis[v]=true;st.push_back({v,u});}
else if(v!=par){cyc=true;break;}}}}
printf("%s\n",cyc?"YES":"NO");return 0;}

